:root {
  --bg-card: #fdf8f0;
  --bg-header: #4a3728;
  --bg-metric: #f5ede0;
  --bg-footer: #efe5d3;
  --accent-primary: #c8783a;
  --accent-green: #5a7a52;
  --accent-blue: #4a6d8c;
  --text-dark: #2e2018;
  --text-mid: #6b5040;
  --text-light: #9b7d68;
  --text-header: #f5ede0;
  --tag-type-bg: #e8d5bc;
  --tag-milk-bg: #d8e8d5;
  --tag-status-bg: #d5e0e8;
  --border-color: #ddc9b0;
  --progress-bg: #ddc9b0;
  --progress-fill: #c8783a;
  --btn-primary-bg: #4a3728;
  --btn-secondary-bg: #fff;
}

.cheese-log {
  background-color: var(--bg-card);
  border: 2px solid var(--border-color);
  border-radius: 14px;
  overflow: hidden;
  width: 460px;
  font-size: 14px;
  color: var(--text-dark);
}

.log-header {
  background-color: var(--bg-header);
  padding: 12px 18px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.header-left {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.log-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--accent-primary);
}

.log-title {
  font-size: 18px;
  font-weight: 700;
  color: var(--text-header);
  margin: 0;
}

.header-right {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 3px;
}

.batch-id {
  font-size: 12px;
  font-weight: 700;
  color: var(--accent-primary);
  letter-spacing: 1px;
}

.log-date {
  font-size: 11px;
  color: var(--text-header);
  opacity: 0.75;
}

.cheese-profile {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px 18px;
  border-bottom: 1px solid var(--border-color);
}

.cheese-icon {
  font-size: 42px;
  margin: 0;
  line-height: 1;
  width: 52px;
  text-align: center;
}

.profile-details {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.cheese-name {
  font-size: 17px;
  font-weight: 700;
  color: var(--text-dark);
  margin: 0;
}

.cheese-origin {
  font-size: 12px;
  color: var(--text-light);
  margin: 0;
}

.tag-row {
  display: flex;
  gap: 6px;
  margin-top: 2px;
}

.tag {
  font-size: 11px;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 20px;
  letter-spacing: 0.3px;
}

.tag-type {
  background-color: var(--tag-type-bg);
  color: var(--text-mid);
}

.tag-milk {
  background-color: var(--tag-milk-bg);
  color: var(--accent-green);
}

.tag-status {
  background-color: var(--tag-status-bg);
  color: var(--accent-blue);
}

.metrics-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0;
  border-bottom: 1px solid var(--border-color);
}

.metric {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 12px 8px;
  background-color: var(--bg-metric);
  border-right: 1px solid var(--border-color);
  gap: 3px;
}

.metric:last-child {
  border-right: none;
}

.metric-value {
  font-size: 18px;
  font-weight: 700;
  color: var(--accent-primary);
}

.metric-label {
  font-size: 11px;
  color: var(--text-light);
  font-weight: 500;
  text-align: center;
}

.log-footer {
  background-color: var(--bg-footer);
  padding: 12px 18px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.progress-wrap {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: 1;
}

.progress-label {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-mid);
  white-space: nowrap;
}

.progress-bar {
  flex: 1;
  height: 8px;
  background-color: var(--progress-bg);
  border-radius: 4px;
  overflow: hidden;
}

.progress-fill {
  width: 59%;
  height: 100%;
  background-color: var(--progress-fill);
  border-radius: 4px;
}

.progress-pct {
  font-size: 12px;
  font-weight: 700;
  color: var(--accent-primary);
}

.footer-actions {
  display: flex;
  gap: 8px;
}

.btn {
  padding: 7px 14px;
  border-radius: 7px;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  border: 1.5px solid var(--border-color);
}

.btn-secondary {
  background-color: var(--btn-secondary-bg);
  color: var(--text-mid);
}

.btn-primary {
  background-color: var(--btn-primary-bg);
  color: var(--text-header);
  border-color: var(--btn-primary-bg);
}
